#include <iostream>

// Function to find the nth Fibonacci number using recursion
int fibonacci(int n) {
    if (n <= 1) {
        return n;
    }
    return fibonacci(n - 1) + fibonacci(n - 2);
}

int main() {
    int n;
    std::cout << "Enter the value of n: ";
    std::cin >> n;

    int fibonacci_number = fibonacci(n);
    std::cout << "The " << n << "th Fibonacci number is: " << fibonacci_number << std::endl;

    return 0;
}
